// NoteChanged: A file was created or its content changed, by a write or on
// disk.
type NoteChanged struct {
	VaultID int64         `json:"vaultId"`
	Path    string        `json:"path"`
	Hash    string        `json:"hash"`
	Source  VersionSource `json:"source"`
}

// EventName is the wire name of NoteChanged.
func (NoteChanged) EventName() string { return "note.changed" }

// Durable reports whether NoteChanged is kept in the changes log.
func (NoteChanged) Durable() bool { return true }

// NoteMoved: A file was renamed or moved.
type NoteMoved struct {
	VaultID int64  `json:"vaultId"`
	From    string `json:"from"`
	To      string `json:"to"`
}

// EventName is the wire name of NoteMoved.
func (NoteMoved) EventName() string { return "note.moved" }

// Durable reports whether NoteMoved is kept in the changes log.
func (NoteMoved) Durable() bool { return true }

// NoteRemoved: A file was deleted, by note.delete or on disk.
type NoteRemoved struct {
	VaultID int64  `json:"vaultId"`
	Path    string `json:"path"`
}

// EventName is the wire name of NoteRemoved.
func (NoteRemoved) EventName() string { return "note.removed" }

// Durable reports whether NoteRemoved is kept in the changes log.
func (NoteRemoved) Durable() bool { return true }

// ---- rpc ----

// Hello: Server identity and the negotiated protocol.
type Hello struct {
	// Protocol major version the server speaks.
	Protocol int64 `json:"protocol"`
	// Server name and version, for logs.
	Server string `json:"server"`
}

// RPCHelloParams holds the params of rpc.hello.
type RPCHelloParams struct {
	// Protocol major version the client speaks.
	Protocol int64 `json:"protocol"`
	// Client name and version, for logs.
	Client string `json:"client"`
}

// RPCService: Connection setup. A client calls rpc.hello first on every
// connection; the server answers any other method with notReady until hello
// succeeds.
type RPCService interface {
	// Hello implements rpc.hello. Negotiate the protocol major version. Changes
	// within a major version are additive only.
	Hello(ctx context.Context, p *RPCHelloParams) (*Hello, error)
}

func registerRPC(r *Router, s RPCService) {
	callers := []Caller{CallerLocal, CallerSession, CallerDevice}
	r.handle("rpc.hello", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p RPCHelloParams
		if err := decodeParams(raw, &p, []string{"protocol", "client"}); err != nil {
			return nil, err
		}
		return s.Hello(ctx, &p)
	})
}

// RPCClient calls the rpc methods; it implements RPCService.
type RPCClient struct{ c *Client }

// RPC returns the rpc methods.
func (c *Client) RPC() RPCClient { return RPCClient{c} }

var _ RPCService = RPCClient{}

// Hello calls rpc.hello.
func (x RPCClient) Hello(ctx context.Context, p *RPCHelloParams) (*Hello, error) {
	var r Hello
	err := x.c.Call(ctx, "rpc.hello", p, &r)
	if err != nil {
		return nil, err
	}
	return &r, nil
}

// ---- sync ----

// SyncState: What a vault's sync is doing.
type SyncState string

const (
	// In step with the hub as far as the device knows.
	SyncStateIdle SyncState = "idle"
	// Pushing or pulling.
	SyncStateSyncing SyncState = "syncing"
	// The hub cannot be reached; changes wait and sync on reconnect.
	SyncStateOffline SyncState = "offline"
	// The hub refused the device token: pair again.
	SyncStateRevoked SyncState = "revoked"
	// The hub no longer serves the vault as the device knew it: sync.reset.
	SyncStateReset SyncState = "reset"
)

// Valid reports whether v is one of the declared values.
func (v SyncState) Valid() bool {
	switch v {
	case SyncStateIdle, SyncStateSyncing, SyncStateOffline, SyncStateRevoked, SyncStateReset:
		return true
	}
	return false
}

// PairingState: Where a pairing stands.
type PairingState string

const (
	// Waiting for the user to approve the code on the hub.
	PairingStatePending PairingState = "pending"
	// Approved; the device keeps its token.
	PairingStateApproved PairingState = "approved"
	// Not approved within 10 minutes.
	PairingStateExpired PairingState = "expired"
)

// Valid reports whether v is one of the declared values.
func (v PairingState) Valid() bool {
	switch v {
	case PairingStatePending, PairingStateApproved, PairingStateExpired:
		return true
	}
	return false
}

// Pairing: A pairing the device started.
type Pairing struct {
	// Its ID, for sync.paired.
	Pairing string `json:"pairing"`
	// The one-time code to approve on the hub, as XXXX-XXXX.
	Code string `json:"code"`
	// The hub's ID.
	Hub       string    `json:"hub"`
	URL       string    `json:"url"`
	ExpiresAt time.Time `json:"expiresAt"`
}

// PairResult: A pairing's state.
type PairResult struct {
	State PairingState `json:"state"`
	// The hub's ID.
	Hub string `json:"hub"`
}

// SyncHub: A hub this device paired with.
type SyncHub struct {
	ID int64 `json:"id"`
	// The hub's ID.
	Hub string `json:"hub"`
	URL string `json:"url"`
	// This device's ID on the hub.
	Device   int64     `json:"device"`
	PairedAt time.Time `json:"pairedAt"`
}

// SyncRefusal: A local change the hub refused; it is not pushed again until
// the file changes.
type SyncRefusal struct {
	Path   string       `json:"path"`
	Reason RefuseReason `json:"reason"`
	At     time.Time    `json:"at"`
}

// SyncStatus: A synced vault's state.
type SyncStatus struct {
	VaultID int64 `json:"vaultId"`
	// The hub's URL.
	URL string `json:"url"`
	// The hub vault's name.
	HubVault string    `json:"hubVault"`
	State    SyncState `json:"state"`
	// The highest sequence number whose heads the device applied.
	Cursor int64 `json:"cursor"`
	// The hub log's latest sequence number, as last seen.
	HubSeq int64 `json:"hubSeq"`
	// Files with a change to push, and local conflict versions not yet pushed.
	Pending int64 `json:"pending"`
	// Flagged files.
	Conflicts int64         `json:"conflicts"`
	Refused   []SyncRefusal `json:"refused"`
	// Pulled paths this device ignores or cannot hold.
	Skipped []string `json:"skipped"`
	// When the device was last in step with the hub.
	SyncedAt *time.Time `json:"syncedAt,omitzero"`
	// The last failure, while offline, revoked or reset.
	Error *string `json:"error,omitzero"`
}

// SyncConflict: A flagged file and the conflict revisions since its last
// resolve.
type SyncConflict struct {
	Path string `json:"path"`
	// The hub's file ID.
	File      int64      `json:"file"`
	Revisions []Revision `json:"revisions"`
}

