// EventName is the wire name of VaultConfigured.
func (VaultConfigured) EventName() string { return "vault.configured" }

// Durable reports whether VaultConfigured is kept in the changes log.
func (VaultConfigured) Durable() bool { return true }

// VaultRemoved: A vault was forgotten.
type VaultRemoved struct {
	ID int64 `json:"id"`
}

// EventName is the wire name of VaultRemoved.
func (VaultRemoved) EventName() string { return "vault.removed" }

// Durable reports whether VaultRemoved is kept in the changes log.
func (VaultRemoved) Durable() bool { return true }

// Services is one implementation per domain, for NewRouter.
type Services struct {
	Events EventsService
	Hub    HubService
	Log    LogService
	Note   NoteService
	RPC    RPCService
	Sync   SyncService
	Vault  VaultService
}

func (s Services) register(r *Router) error {
	if s.Events == nil {
		return errors.New("api: Services.Events is nil")
	}
	registerEvents(r, s.Events)
	if s.Hub == nil {
		return errors.New("api: Services.Hub is nil")
	}
	registerHub(r, s.Hub)
	if s.Log == nil {
		return errors.New("api: Services.Log is nil")
	}
	registerLog(r, s.Log)
	if s.Note == nil {
		return errors.New("api: Services.Note is nil")
	}
	registerNote(r, s.Note)
	if s.RPC == nil {
		return errors.New("api: Services.RPC is nil")
	}
	registerRPC(r, s.RPC)
	if s.Sync == nil {
		return errors.New("api: Services.Sync is nil")
	}
	registerSync(r, s.Sync)
	if s.Vault == nil {
		return errors.New("api: Services.Vault is nil")
	}
	registerVault(r, s.Vault)
	return nil
}

