// EventAdmits reports whether the domain of the named event admits
// caller: the server delivers an event only to connections of the callers
// its domain admits, as Router.Dispatch does for methods.
func EventAdmits(name string, caller Caller) bool {
	switch name {
	case "log.appended":
		return caller == CallerDevice
	case "note.changed":
		return caller == CallerLocal
	case "note.moved":
		return caller == CallerLocal
	case "note.removed":
		return caller == CallerLocal
	case "sync.changed":
		return caller == CallerLocal
	case "vault.scan":
		return caller == CallerLocal
	case "vault.added":
		return caller == CallerLocal
	case "vault.configured":
		return caller == CallerLocal
	case "vault.removed":
		return caller == CallerLocal
	}
	return false
}

// DecodeEvent decodes the data of the named event.
func DecodeEvent(name string, data jsontext.Value) (Event, error) {
	switch name {
	case "log.appended":
		var e LogAppended
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "note.changed":
		var e NoteChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "note.moved":
		var e NoteMoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "note.removed":
		var e NoteRemoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "sync.changed":
		var e SyncChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.scan":
		var e VaultScan
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.added":
		var e VaultAdded
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.configured":
		var e VaultConfigured
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.removed":
		var e VaultRemoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	}
	return nil, fmt.Errorf("unknown event %q", name)
}
